select 'price_snapshot', ps.id, 'amount_low_minor', 'c8cbd4a9c6e59296524f91b03786cd826b97436d1c01db110dc1484837543c0b', (select id from public.sources where url = 'https://www.seikoboutique.co.uk/product/seiko-prospex-solar-divers-in-all-black-sne599/' and retrieved_at = '2026-08-30T20:54:24Z'::timestamptz),
